// Shared helpers. build.py pastes this file into every Code node that has the
// include line at its top, so n8n needs no external modules.

// Same algorithm runs in the Apps Script seeder, so a vendor keeps one ID
// from the first email through the form and the assessment.
function vendorIdFor(email) {
  const s = String(email || '').trim().toLowerCase();
  let h = 5381;
  for (let i = 0; i < s.length; i++) h = ((h * 33) ^ s.charCodeAt(i)) >>> 0;
  return 'EBM-V-' + h.toString(36).toUpperCase().padStart(7, '0').slice(-7);
}

// Models sometimes wrap JSON in fences or add a sentence before it.
function parseJson(text) {
  if (!text || typeof text !== 'string') return null;
  const cleaned = text.replace(/```(?:json)?/gi, '');
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start < 0 || end <= start) return null;
  try { return JSON.parse(cleaned.slice(start, end + 1)); } catch (e) { return null; }
}

function llmText(response) {
  const choice = response && response.choices && response.choices[0];
  return (choice && choice.message && choice.message.content) || '';
}

function esc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function clip(s, n) {
  s = String(s == null ? '' : s).replace(/\s+\n/g, '\n').trim();
  return s.length > n ? s.slice(0, n) + '…' : s;
}

// Maps Google Form column titles to field keys and joins each response to the
// email the vendor first sent us.

const FIELDS = [
  {
    "key": "vendor_id",
    "title": "Reference ID"
  },
  {
    "key": "company_name",
    "title": "Company legal name"
  },
  {
    "key": "contact_name",
    "title": "Contact person"
  },
  {
    "key": "contact_email",
    "title": "Contact email"
  },
  {
    "key": "phone",
    "title": "Phone"
  },
  {
    "key": "category",
    "title": "Supply category"
  },
  {
    "key": "offering",
    "title": "What do you supply?"
  },
  {
    "key": "website",
    "title": "Company website"
  },
  {
    "key": "city",
    "title": "City"
  },
  {
    "key": "years_in_business",
    "title": "Years in business"
  },
  {
    "key": "ntn",
    "title": "NTN"
  },
  {
    "key": "strn",
    "title": "STRN"
  },
  {
    "key": "secp_no",
    "title": "SECP registration number"
  },
  {
    "key": "directors",
    "title": "Owners or directors (full names)"
  },
  {
    "key": "certifications",
    "title": "Certifications held"
  },
  {
    "key": "cert_expiry",
    "title": "Certificate expiry dates"
  },
  {
    "key": "turnover",
    "title": "Annual turnover (PKR)"
  },
  {
    "key": "capacity",
    "title": "Monthly capacity"
  },
  {
    "key": "key_clients",
    "title": "Key clients"
  },
  {
    "key": "payment_terms",
    "title": "Payment terms offered"
  },
  {
    "key": "related_party",
    "title": "Is any owner or director related to an EBM employee?"
  },
  {
    "key": "related_party_details",
    "title": "If yes, give the name and relationship"
  },
  {
    "key": "litigation",
    "title": "Any litigation, debarment or regulatory action in the last 5 years?"
  },
  {
    "key": "litigation_details",
    "title": "If yes, give details"
  },
  {
    "key": "declaration",
    "title": "Declaration"
  }
];

const intake = {};
for (const row of $('Read Intake').all()) {
  if (row.json.vendor_id) intake[row.json.vendor_id] = row.json;
}

return $('Form Response Trigger').all().map(({ json: row }) => {
  const v = {};
  for (const f of FIELDS) v[f.key] = String(row[f.title] == null ? '' : row[f.title]).trim();

  v.contact_email = v.contact_email.toLowerCase();
  // A vendor who opens a forwarded or bare form link has no reference ID.
  if (!/^EBM-V-/.test(v.vendor_id)) v.vendor_id = vendorIdFor(v.contact_email);
  v.form_submitted_at = row.Timestamp || new Date().toISOString();
  v.website = v.website.replace(/^https?:\/\//i, '').replace(/\/$/, '');

  const first = intake[v.vendor_id] || {};
  v.original_email = first.email_body ? `Subject: ${first.subject}\n\n${first.email_body}` : '';
  return { json: v };
});

// Three web searches per vendor: who they are, anything adverse about the
// company or its directors, and what their own site claims.

const out = [];
for (const { json: v } of $input.all()) {
  const name = `"${v.company_name}"`;
  const people = v.directors
    .replace(/\(.*?\)/g, '')
    .split(/[,;\n]| and /)
    .map(s => s.trim())
    .filter(s => s.split(' ').length >= 2)
    .slice(0, 2)
    .map(s => `"${s}"`);

  const queries = [
    `${name} ${v.city} Pakistan`,
    `${[name, ...people].join(' OR ')} fraud OR lawsuit OR debarred OR adulteration OR penalty OR FIR`,
    v.website ? `${v.website} ${v.company_name} certification clients` : `${name} ${v.offering.split(/[,.]/)[0]} supplier reviews`,
  ];
  queries.forEach((query, n) => out.push({
    json: { vendor_id: v.vendor_id, purpose: ['profile', 'adverse', 'claims'][n], query },
  }));
}
return out;

